  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, '0');
  const seconds = (totalSeconds % 60).toString().padStart(2, '0');
  return `${minutes}:${seconds}`;
};

export default function ChallengerDashboard() {
  const router = useRouter();
  const { socket, isConnected } = useSocket();

  const [availableElites, setAvailableElites] = useState<Participant[]>([]);
  const [bountyQuestions, setBountyQuestions] = useState<BountyQuestion[]>([]);
  const [pendingRequests, setPendingRequests] = useState<Set<string>>(new Set());
  const [timeRemaining, setTimeRemaining] = useState(0);
  const [roundEndTime, setRoundEndTime] = useState<number | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRedirecting, setIsRedirecting] = useState(false);
  const [userRole, setUserRole] = useState<'elite' | 'challenger' | null>(null);
  const [hasActiveSession, setHasActiveSession] = useState(false);

  // Fetch initial state and dashboard data using state-based approach
  useEffect(() => {
    if (!socket || !isConnected) return;

    console.debug('[Challenger] Fetching round2 state...');

    // Set a timeout to prevent infinite loading
    const stateTimeout = setTimeout(() => {
      console.error('[Challenger] GetState/Dashboard timeout');
      setIsLoading(false);
      showErrorToast('Failed to load dashboard. Please refresh.');
    }, 10000); // 10 second timeout

    // Listen for state updates from server
    const handleStateUpdate = (stateResponse: any) => {
      console.debug('[Challenger] State response:', stateResponse);

      if (!stateResponse.success) {
        clearTimeout(stateTimeout);
        showErrorToast(stateResponse.error || "Failed to load state");
        setIsLoading(false);
        return;
      }

      const role = stateResponse.roundSpecific?.role;
      const session = stateResponse.session;
      const bountyQuestions = stateResponse.roundSpecific?.bountyQuestions || [];

      setUserRole(role);
      setHasActiveSession(!!session);

      // If user has active session, redirect to code page
      if (session) {
        clearTimeout(stateTimeout);
        setIsLoading(false);
        showInfoToast("Resuming your active session...");
        setTimeout(() => {
          router.push('/r2/code');
        }, 1000);
        return;
      }

      // If user is not a challenger, redirect
      if (role !== 'challenger') {
        clearTimeout(stateTimeout);
        setIsLoading(false);
        showErrorToast("Access denied. Redirecting...");
        setTimeout(() => {
          router.push(role ? `/r2/${role}` : '/dashboard');
        }, 1000);
        return;
      }

      // User is a challenger with no active session - set dashboard data from state
      setRoundEndTime(stateResponse.round?.endTime || null);
      const transformedBounties = bountyQuestions.map((q: any) => ({
        ...q,
        name: q.title,
      }));
      setBountyQuestions(transformedBounties);

      const allParticipants = stateResponse.participants?.all || [];
      setAvailableElites(allParticipants.filter((p: Participant) => p.role === 'elite' && p.status === 'elite:idle'));

      clearTimeout(stateTimeout);
      setIsLoading(false);
    };

    // Register listener
    socket.on('round2:state', handleStateUpdate);

    // Request state from server
    socket.emit('round2:getState');

    return () => {
      socket.off('round2:state', handleStateUpdate);
      clearTimeout(stateTimeout);
    };
  }, [socket, isConnected, router]);

  // --- MODIFIED: Timer now triggers redirection ---
  useEffect(() => {
    if (!roundEndTime || isRedirecting) return;
    const interval = setInterval(() => {
      const remaining = roundEndTime - Date.now();
      setTimeRemaining(Math.max(0, remaining));
      if (remaining <= 0) {
        clearInterval(interval);
        // --- FIX: Redirect when timer hits zero ---
        if (!isRedirecting) {
          setIsRedirecting(true);
          showInfoToast("Round 2 has ended. You will be redirected to the dashboard.");
          setTimeout(() => {
            router.push('/dashboard');
          }, 3000);
        }
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [roundEndTime, router, isRedirecting]);

  useEffect(() => {
    if (!socket) return;

    const handleRound2Redirect = ({ target, reason }: { target: string; reason?: string }) => {
      console.log('[ROUND2 REDIRECT]', { target, reason });

      if (isRedirecting) return;

      setIsRedirecting(true);

      if (target === 'lobby') {
        showInfoToast(reason || 'You have been removed from Round 2');
        router.replace('/dashboard');
      }
    };


    const handleLobbyUpdate = (data: { participants: Participant[] }) => {
      setAvailableElites(data.participants.filter(p => p.role === 'elite' && p.status === 'elite:idle'));
    };

    const handleRequestFailed = (data: { eliteId: string, reason?: string }) => {
      showInfoToast(data.reason || `Your challenge was rejected.`);
      setPendingRequests(prev => {
        const newSet = new Set(prev);
        newSet.delete(data.eliteId);
        return newSet;
      });
    };

    const handleMatchStarted = (data: { matchId: string }) => {
      showSuccessToast("Match starting! Redirecting...");
      try {
        sessionStorage.setItem('r2_session_type', 'match');
        sessionStorage.setItem('r2_context_id', data.matchId);
        sessionStorage.setItem('r2_user_role', 'challenger');
        router.push(`/r2/code`);
      } catch (error) {
        console.error("Session storage is unavailable.", error);
        showErrorToast("Could not save session. Please enable cookies/storage.");
      }
    };

    const handleDashboardUpdate = (data: { pendingRequests?: string[] }) => {
      if (data.pendingRequests) {
        setPendingRequests(new Set(data.pendingRequests));
      }
    };

    const handleRoundEnd = () => {
      // --- FIX: Use safeguard to prevent double redirection ---
      if (isRedirecting) return;
      setIsRedirecting(true);
      showInfoToast("Round 2 has ended. You will be redirected to the dashboard.");
      setTimeout(() => {
        router.push('/dashboard');
      }, 3000);
    };

    socket.on('round2:redirect', handleRound2Redirect);
    socket.on('round2:lobbyUpdate', handleLobbyUpdate);
    socket.on('round2:challengeRejected', handleRequestFailed);
    socket.on('round2:challengeExpired', handleRequestFailed);
    socket.on('round2:matchStarted', handleMatchStarted);
    socket.on('round2:dashboardUpdate', handleDashboardUpdate);
    socket.on('round2:ended', handleRoundEnd);

    return () => {
      socket.off('round2:lobbyUpdate', handleLobbyUpdate);
      socket.off('round2:challengeRejected', handleRequestFailed);
      socket.off('round2:challengeExpired', handleRequestFailed);
      socket.off('round2:matchStarted', handleMatchStarted);
      socket.off('round2:dashboardUpdate', handleDashboardUpdate);
      socket.off('round2:ended', handleRoundEnd);
      socket.off('round2:redirect', handleRound2Redirect);
    };
  }, [socket, router, isRedirecting]);

  const handleStartBounty = (questionId: string) => {
    if (!socket) return;

    socket.emit('round2:bountyBeginQuestion', { questionId }, (response: SimpleSocketResponse) => {
      if (response.success) {
        showSuccessToast("Starting bounty... good luck!");
        try {
          sessionStorage.setItem('r2_session_type', 'bounty');
          sessionStorage.setItem('r2_context_id', questionId);
          sessionStorage.setItem('r2_user_role', 'challenger');
          router.push(`/r2/code`);
        } catch (error) {
          console.error("Session storage is unavailable.", error);
          showErrorToast("Could not save session. Please enable cookies/storage.");
        }
      } else {
        showErrorToast(response.message || "Could not start bounty.");
      }
    });
  };

  const handleChallengeElite = (eliteId: string) => {
    if (!socket) return;
    setPendingRequests(prev => new Set(prev).add(eliteId));
    socket.emit('round2:challengeRequest', { eliteId }, (response: SimpleSocketResponse) => {
      if (response.success) {
        showSuccessToast("Challenge request sent!");
      } else {
        showErrorToast(response.message || "Failed to send challenge.");
        setPendingRequests(prev => {
          const newSet = new Set(prev);
          newSet.delete(eliteId);
          return newSet;
        });
        if (response.message?.includes("active session")) {
          router.refresh();
        }
      }
    });
  };

  if (isLoading) {
    return <LoadingOverlay isLoading={true} message="Loading Challenger Dashboard..." />;
  }

  return (
    <div className="flex bg-[url('/bg_elite.jpg')] bg-center bg-no-repeat h-screen w-full flex-col overflow-hidden orbitron">
      <div className="flex-1 flex items-center justify-center text-6xl orbitron white-glow relative">
        <Image src="/b-2.svg" alt="Battlecode Logo" className="h-20" width={80} height={80} />
        CHALLENGER
        <div className="absolute top-4 right-4 bg-black/50 text-white text-2xl p-2 px-4 rounded-lg font-mono">
          {formatTime(timeRemaining)}
        </div>
      </div>
      <div className="flex-4 flex flex-row">
        <div className="flex-1">
          <div className="h-[80%] w-[80%] glass-box rounded-lg m-auto mt-10 p-5">
            <h2 className="text-2xl font-bold text-white mb-4 ml-4 orbitron">Challenge Elites</h2>
            <CustomScrollbar className="h-[calc(100%-3rem)] overflow-y-auto overflow-x-hidden pr-2">
              {availableElites.length > 0 ? (
                availableElites.map((player) => (
                  <ChallengerPlayerCard
                    key={player.id}
                    username={player.username}
                    onChallenge={() => handleChallengeElite(player.id)}
                    isPending={pendingRequests.has(player.id)}
                  />
                ))
              ) : (
                <div className="text-center text-gray-400 mt-8">
                  <p className="text-lg">No elites are available</p>
                  <p className="text-sm">All elites are currently in a match. Check back soon!</p>
                </div>
              )}
            </CustomScrollbar>
          </div>
        </div>
        <div className="flex-1">
          <div className="h-[80%] w-[80%] glass-box rounded-lg m-auto mt-10 p-5">
            <h2 className="text-2xl font-bold text-white mb-4 orbitron">Bounty Questions</h2>
            <CustomScrollbar className="h-[calc(100%-3rem)] overflow-y-auto pr-2">
              <div className="grid grid-cols-4 gap-2">
                {bountyQuestions.map((question, index) => (
                  <BountyQuestionCard
                    key={question.id}
                    question={question}
                    onSolve={() => handleStartBounty(question.id)}
                    questionIndex={index}
                  />
                ))}
              </div>
            </CustomScrollbar>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import Editor, { useMonaco } from '@monaco-editor/react';
import * as monaco from 'monaco-editor';
import { useAuth } from '@/contexts/AuthContext';
import CustomScrollbar from '@/components/shared/CustomScrollbar';
import Button from '@/components/shared/ColoredBtn';
import { showErrorToast, showInfoToast, showSuccessToast } from '@/components/shared/CustomToast';
import SecureWrapper from '@/components/shared/SecureWrapper';

interface Problem {
  id: string;
  title: string;
  description: string;
  difficulty: string;
  constraints: string[];
  boilerplate: { [key: string]: string };
  sampleTestCases: TestCase[];
  hiddenTestCases?: TestCase[];
  testCases?: TestCase[];
  hints: string[];
  avgTimeComplexity?: string;
  avgSpaceComplexity?: string;
}

interface TestCase {
  stdin?: string;
  expected_output?: string;
  input?: {
    stdin?: string;
    json?: any;
  };
  output?: {
    stdout?: string;
    json?: any;
  };
  explanation?: string;
}

interface SubmissionResult {
  token: string;
  status: {
    id: number;
    description: string;
  };
  stdout: string | null;
  stderr: string | null;
  compile_output: string | null;
  time: string | null;
  memory: string | null;
}

interface CodePageProps {
  round: string;
  currentProblem: Problem | null;
  problems: Problem[];
  currentProblemIndex: number;
  timeRemaining: number;
  roundDuration: number;
  isRoundActive: boolean;
  isLoading: boolean;
  onNextQuestion?: () => void;
  onReturnToLobby?: () => void;
}

export default function CodePage({ 
  round,
  currentProblem,
  problems,
  currentProblemIndex,
  timeRemaining,
  roundDuration,
  isRoundActive,
  isLoading,
  onNextQuestion,
  onReturnToLobby
}: CodePageProps) {
  const router = useRouter();
  const { user, session } = useAuth();

  const [code, setCode] = useState("");
  const [language, setLanguage] = useState("python");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRunning, setIsRunning] = useState(false);
  const [submissionResults, setSubmissionResults] = useState<SubmissionResult[] | null>(null);
  const [showHints, setShowHints] = useState(false);
  
  const [codeEditorHeight, setCodeEditorHeight] = useState(60);
  const [isDragging, setIsDragging] = useState(false);

  const editorRef = useRef<monaco.editor.IStandaloneCodeEditor | null>(null);

  const editorOptions = {
    minimap: { enabled: false },
    fontSize: 14,
    lineNumbers: 'on' as const,
    roundedSelection: false,
    scrollBeyondLastLine: false,
    automaticLayout: true,
    tabSize: 2,
    wordWrap: 'on' as const,
    bracketPairColorization: { enabled: true },
    autoIndent: 'full' as const,
    formatOnPaste: true,
    formatOnType: true,
  };

  const getMonacoLanguage = (lang: string) => {
    const languageMap: { [key: string]: string } = {
      'python': 'python',
      'java': 'java',
      'cpp': 'cpp',
      'c': 'c',
      'javascript': 'javascript',
    };
    return languageMap[lang] || 'python';
  };

  const monaco = useMonaco();
  
  useEffect(() => {
    if (monaco) {
      monaco.editor.defineTheme('custom-dark', {
        base: 'vs-dark',
        inherit: true,
        rules: [
          { token: 'comment', foreground: '#6A9955' },
          { token: 'keyword', foreground: '#569CD6' },
          { token: 'string', foreground: '#CE9178' },
          { token: 'number', foreground: '#B5CEA8' },
        ],
        colors: {
          'editor.background': '#0a0a0a',
          'editor.foreground': '#ffffff',
          'editor.lineHighlightBackground': '#1a1a1a',
          'editor.selectionBackground': '#264f78',
          'editor.inactiveSelectionBackground': '#3a3d41',
          'editorCursor.foreground': '#f97316',
          'editorLineNumber.foreground': '#858585',
          'editorLineNumber.activeForeground': '#f97316',
          'editor.selectionHighlightBackground': '#ADD6FF26',
          'editor.wordHighlightBackground': '#575757B8',
          'editorBracketMatch.background': '#0064001a',
          'editorBracketMatch.border': '#888888',
        },
      });
      monaco.editor.setTheme('custom-dark');
    }
  }, [monaco]);

  useEffect(() => {
    try {
      if (currentProblem && currentProblem.boilerplate) {
        const newCode = currentProblem.boilerplate[language] || currentProblem.boilerplate['python'] || '';
        setCode(newCode);
      }
    } catch (error) {
      console.error('Error updating code for language change:', error);
    }
  }, [language, currentProblem]);

  function handleEditorMount(
    editor: monaco.editor.IStandaloneCodeEditor,
    monacoInstance: typeof import('monaco-editor')
  ){
    editorRef.current = editor;

    //comment here to enable copy-paste
    // Disable paste via context menu
    editor.addAction({
      id: "disable-paste",
      label: "Paste",
      keybindings: [],
      precondition: "false",
      run: () => {}
    });
    // Block DOM paste events
    const domNode = editor.getDomNode();
    if (domNode) {
      domNode.addEventListener("paste", (e: ClipboardEvent) => {
        e.preventDefault();
        showErrorToast("Paste is disabled");
      }, true);
    }
    // Block keyboard shortcut Ctrl/Cmd+V
    editor.addCommand(monacoInstance.KeyMod.CtrlCmd | monacoInstance.KeyCode.KeyV, () => {
      showErrorToast("Paste shortcut is disabled");
    });
  }
  //till here

  const executeCode = async (isSubmission = false) => {
    if (!currentProblem) {
      showErrorToast('No problem loaded');
      return;
    }

    const action = isSubmission ? 'submitting' : 'running';
    showInfoToast(`${action.charAt(0).toUpperCase() + action.slice(1)} your code...`);
    
    if (isSubmission) {
      setIsSubmitting(true);
    } else {
      setIsRunning(true);
    }

    try {
      const languageIds: { [key: string]: number } = {
        'python': 71,
        'java': 62,
        'cpp': 54,
        'c': 50,
        'javascript': 63
      };

      const languageId = languageIds[language] || 71;

      const testCasesToRun = isSubmission ? 
        (currentProblem.hiddenTestCases || currentProblem.testCases || currentProblem.sampleTestCases) : 
        currentProblem.sampleTestCases;

      if (!testCasesToRun || testCasesToRun.length === 0) {
        throw new Error('No test cases available');
      }

      const submissions = testCasesToRun.map((testCase, index) => {
        try {
          const inputData = testCase.stdin || testCase.input?.stdin || JSON.stringify(testCase.input?.json) || '';
          const expectedOutput = testCase.expected_output || testCase.output?.stdout || JSON.stringify(testCase.output?.json) || '';
          
          return {
            language_id: languageId,
            source_code: btoa(code),
            stdin: btoa(inputData),
            expected_output: btoa(expectedOutput)
          };
        } catch (encodeError) {
          console.error(`Error encoding test case ${index}:`, encodeError);
          throw new Error(`Failed to encode test case ${index + 1}`);
        }
      });

      const apiUrl = process.env.NEXT_PUBLIC_API_URL;
      if (!apiUrl) {
        throw new Error('API URL not configured');
      }

      const response = await fetch(`${apiUrl}/execute-batch`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${session?.access_token}`
        },
        body: JSON.stringify({ submissions })
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => 'Unknown error');
        throw new Error(`HTTP error! status: ${response.status}, message: ${errorText}`);
      }

      const results = await response.json();
      
      if (!Array.isArray(results)) {
        throw new Error('Invalid response format from execution service');
      }
      
      const formattedResults: SubmissionResult[] = results.map((result: any, index: number) => ({
        token: result.token || `test_${index}`,
        status: {
          id: result.status?.id || 3,
          description: result.status?.description || 'Accepted'
        },
        stdout: result.stdout || null,
        stderr: result.stderr || null,
        compile_output: result.compile_output || null,
        time: result.time || null,
        memory: result.memory || null
      }));

      setSubmissionResults(formattedResults);

      const passedTests = formattedResults.filter(r => r.status.description === 'Accepted').length;
      const totalTests = formattedResults.length;

      if (isSubmission) {
        if (passedTests === totalTests) {
          showSuccessToast(`≡ƒÄë All ${totalTests} test cases passed!`);
        } else {
          showErrorToast(`${passedTests}/${totalTests} test cases passed`);
        }
      } else {
        showInfoToast(`Test run completed: ${passedTests}/${totalTests} passed`);
      }

    } catch (error) {
      console.error('Execution error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
      showErrorToast(`Failed to ${action} code: ${errorMessage}`);
    } finally {
      if (isSubmission) {
        setIsSubmitting(false);
      } else {
        setIsRunning(false);
      }
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    e.preventDefault();
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (!isDragging) return;
    
    const container = document.querySelector('.code-results-container') as HTMLElement;
    if (!container) return;
    
    const rect = container.getBoundingClientRect();
    const containerHeight = rect.height;
    const mouseY = e.clientY - rect.top;
    const newHeightPercentage = Math.max(20, Math.min(80, (mouseY / containerHeight) * 100));
    
    setCodeEditorHeight(newHeightPercentage);
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'row-resize';
      document.body.style.userSelect = 'none';
    } else {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    }

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
  }, [isDragging]);

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getTimerDisplay = (): { time: string; className: string } => {
    const isWarning = timeRemaining <= 300;
    const isCritical = timeRemaining <= 60;
    
    return {
      time: formatTime(timeRemaining),
      className: isCritical ? 'border-red-600 text-red-400' : 
                 isWarning ? 'border-yellow-600 text-yellow-400' : 'border-amber-600'
    };
  };

  const formatTestCaseData = (data: any): string => {
    if (typeof data === 'string') return data;
    if (Array.isArray(data)) return data.join(', ');
    if (typeof data === 'object' && data !== null) {
      const entries = Object.entries(data);
      return entries.map(([key, value]) => {
        if (Array.isArray(value)) {
          return `${key} = [${value.join(', ')}]`;
        }
        return `${key} = ${value}`;
      }).join('\n');
    }
    return String(data);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-black/40 text-white">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-500"></div>
          <p>Loading Round {round}...</p>
        </div>
      </div>
    );
  }

  if (!currentProblem) {
    return (
      <div className="flex items-center justify-center h-screen bg-black/40 text-white">
        <div className="flex flex-col items-center gap-4">
          <p>No active round found or waiting for problems to load...</p>
          <button
            onClick={onReturnToLobby}
            className="px-6 py-2 bg-orange-500 text-white rounded hover:bg-orange-600"
          >
            Return to Lobby
          </button>
        </div>
      </div>
    );
  }

  return (
    //remove this securewrapper also to disable copy paste
    <SecureWrapper>
    <div className="flex flex-col h-screen text-white overflow-hidden bg-[url('/bg-code.svg')] bg-fixed bg-cover bg-center oxanium">
      <div className="flex-1 flex p-4 gap-4 bg-black/40 min-h-0">
        <CustomScrollbar className="w-1/2 flex border rounded-lg border-amber-600 bg-black/40 p-4 flex-col min-h-0 overflow-hidden glass-box">
          <div className="flex justify-between items-start mb-4 flex-shrink-0">
            <div>
              <h2 className="text-2xl font-bold">{currentProblem.title}</h2>
              <div className="flex gap-4 text-sm text-gray-400 mt-1">
                <span>Difficulty: {currentProblem.difficulty}</span>
                <span>Round: {round}</span>
                <span>Question: {currentProblemIndex + 1}/{problems.length}</span>
              </div>
            </div>
            <div className="flex gap-2">
              <Button
                content={showHints ? "Hide" : "Hint≡ƒÆí"}
                onClick={() => setShowHints(!showHints)}
              />
              {currentProblemIndex < problems.length - 1 && onNextQuestion && (
                <button
                  onClick={onNextQuestion}
                  className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
                >
                  Next ΓåÆ
                </button>
              )}
            </div>
          </div>
          
          <div className="flex-1 overflow-y-auto min-h-0">
            {showHints && currentProblem.hints && currentProblem.hints.length > 0 && (
              <div className="mb-4 bg-gray-800 p-3 rounded">
                <h3 className="font-bold mb-2 text-amber-400">Hints:</h3>
                <ul className="list-disc list-inside text-gray-300 space-y-2">
                  {currentProblem.hints.map((hint, i) => <li key={i}>{hint}</li>)}
                </ul>
              </div>
            )}
            
            <p className="mb-4 text-gray-300 whitespace-pre-wrap">{currentProblem.description}</p>

            {currentProblem.constraints && currentProblem.constraints.length > 0 && (
              <>
                <h3 className="font-bold mb-2 text-amber-400">Constraints:</h3>
                <ul className="list-disc list-inside mb-4 text-gray-300 font-mono text-sm">
                  {currentProblem.constraints.map((constraint, i) => (
                    <li key={i}>{constraint}</li>
                  ))}
                </ul>
              </>
            )}

            {currentProblem.sampleTestCases && currentProblem.sampleTestCases.length > 0 && (
              <>
                <h3 className="font-bold mb-4 text-amber-400">Sample Cases:</h3>
                {currentProblem.sampleTestCases.map((testCase, i) => (
                  <div key={i} className="mb-4 bg-gray-800 p-3 rounded font-mono text-sm">
                    <p className="font-bold text-gray-400">Input:</p>
                    <pre className="bg-gray-900 p-2 rounded mt-1 whitespace-pre-wrap">
                      {formatTestCaseData(testCase.stdin || testCase.input?.stdin || testCase.input?.json || '')}
                    </pre>
                    <p className="mt-2 font-bold text-gray-400">Output:</p>
                    <pre className="bg-gray-900 p-2 rounded mt-1 whitespace-pre-wrap">
                      {formatTestCaseData(testCase.expected_output || testCase.output?.stdout || testCase.output?.json || '')}
                    </pre>
                    {testCase.explanation && (
                      <p className="mt-2 text-xs text-gray-400 italic">
                        Explanation: {testCase.explanation}
                      </p>
                    )}
                  </div>
                ))}
              </>
            )}
          </div>
        </CustomScrollbar>

        <div className="w-1/2 flex flex-col code-results-container border-amber-500" style={{ height: '100%' }}>
          <div 
            className="border border-amber-600 rounded-lg p-4 flex flex-col min-h-0"
            style={{ height: `${codeEditorHeight}%`, minHeight: '200px' }}
          >
            <div className="flex justify-between items-center mb-2 gap-2">
              <div className="flex-1 flex gap-2">
                <select
                  value={language}
                  onChange={(e) => setLanguage(e.target.value)}
                  className="bg-gray-800 flex-1 text-white p-2 rounded border border-amber-600 focus:outline-none focus:ring-2 focus:ring-amber-500"
                >
                  <option value="python">Python</option>
                  <option value="java">Java</option>
                  <option value="cpp">C++</option>
                  <option value="c">C</option>
                  <option value="javascript">JavaScript</option>
                </select>
                <div className={`bg-gray-800 flex-1 text-white p-2 rounded border focus:outline-none focus:ring-2 focus:ring-amber-500 text-center font-mono ${
                  getTimerDisplay().className
                }`}>
                  {getTimerDisplay().time}
                </div>
              </div>
              <div className="flex gap-2">
                <button 
                  className="flex items-center gap-2 bg-gray-800 text-white p-2 rounded border border-amber-600 hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-amber-500"
                  onClick={() => executeCode(false)}
                  disabled={isRunning || isSubmitting}
                >
                  <span>Run</span>
                  <img src="/run.svg" className="h-4 w-4"/>
                </button>
                <button 
                  className="bg-gray-800 text-white p-2 rounded border border-amber-600 hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-amber-500"
                  onClick={() => executeCode(true)}
                  disabled={isSubmitting || isRunning}
                >
                  {isSubmitting ? "Submitting..." : "Submit"}
                </button>
              </div>
            </div>
            
            <div className="flex-1 rounded overflow-hidden border border-gray-700">
              <Editor
                height="100%"
                language={getMonacoLanguage(language)}
                value={code}
                onChange={(value) => setCode(value || "")}
                theme="custom-dark"
                options={editorOptions}
                onMount={handleEditorMount}
                loading={
                  <div className="flex items-center justify-center h-full bg-gray-900">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
                  </div>
                }
              />
            </div>
          </div>

          <div
            className={`h-1 bg-amber-600/20 hover:bg-amber-600/40 cursor-row-resize transition-colors duration-200 flex items-center justify-center ${
              isDragging ? 'bg-amber-600/60' : ''
            }`}
            onMouseDown={handleMouseDown}
          >
            <div className="w-8 h-1 bg-amber-600 rounded-full"></div>
          </div>

          <div 
            className="border border-amber-600 rounded-lg p-4 flex flex-col min-h-0"
            style={{ height: `${100 - codeEditorHeight}%`, minHeight: '150px' }}
          >
            <span className="text-lg font-bold flex-shrink-0">Test Results</span>
            <div className="mt-2 flex-grow overflow-y-auto">
              {(isSubmitting || isRunning) && (
                <div className="flex items-center gap-2 text-amber-400">
                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-amber-500"></div>
                  <span>{isSubmitting ? 'Submitting' : 'Running'} your solution...</span>
                </div>
              )}
              {submissionResults && (
                <div className="space-y-2">
                  {submissionResults.map((result, index) => {
                    const isAccepted = result.status.description === "Accepted";
                    const isError = result.status.id > 3;
                    return (
                      <div key={result.token || index} className={`p-2 rounded ${isAccepted ? "bg-green-800/50" : isError ? "bg-red-800/50" : "bg-yellow-800/50"}`}>
                        <p className="font-bold">
                          Test Case {index + 1}:{" "}
                          <span className={`${isAccepted ? "text-green-400" : isError ? "text-red-400" : "text-yellow-400"}`}>
                            {result.status.description}
                          </span>
                        </p>
                        {!isAccepted && (result.stderr || result.compile_output) && (
                          <pre className="text-xs text-red-300 mt-1 whitespace-pre-wrap bg-black/30 p-1 rounded">
                            {result.stderr || result.compile_output}
                          </pre>
                        )}
                        {result.time && (
                          <p className="text-xs text-gray-400 mt-1">
                            Time: {result.time}s | Memory: {result.memory}KB
                          </p>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
    </SecureWrapper>
  );
}

"use client";
import { useEffect, useState, useRef, useCallback, useMemo } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { useSocket } from "@/contexts/SocketContext";
import { useAuth } from "@/contexts/AuthContext";
import Editor, { useMonaco } from '@monaco-editor/react';
import * as monaco from 'monaco-editor';
import { showSuccessToast, showErrorToast, showInfoToast } from '@/components/shared/CustomToast';
import CustomScrollbar from "@/components/shared/CustomScrollbar";
import { Lightbulb, Play } from "lucide-react";
import LoadingOverlay from "@/components/shared/LoadingOverlay";
import SecureWrapper from "@/components/shared/SecureWrapper";


// --- Interfaces ---
interface SessionData {
  type: 'match' | 'bounty';
  opponent?: { id: string; username: string; };
  question: {
    id: string; title: string; description: string; difficulty: string;
    constraints?: string[]; boilerplate?: { [key: string]: string };
    sampleTestCases?: TestCase[]; hints?: string[];
  };
  endTime: number;
}

interface TestCase {
  stdin?: string; expected_output?: string;
  input?: { stdin?: string; json?: unknown; };
  output?: { stdout?: string; json?: unknown; };
  explanation?: string;
}

interface SubmissionResult {
  token: string; status: { id: number; description: string; };
  stdout: string | null; stderr: string | null; compile_output: string | null;
  time: string | null; memory: string | null; passed?: boolean;
}

interface CodeContext {
  round: string; questionId: string; language: string;
}

interface CodeStore {
  [contextKey: string]: string;
}

// --- API & Socket Response Interfaces ---
interface GetCodePageStateResponse {
  success: boolean;
  sessionData?: SessionData;
  message?: string;
}

interface GetStateResponse {
  success: boolean;
  sessionData?: SessionData;
  globalTimeRemaining?: number;
  error?: string;
}

interface MatchResultData {
  winnerId: string;
  loserId: string;
  reason: 'submission' | 'disconnect' | 'timeout' | 'violation';
  newRole: 'elite' | 'challenger';
}

interface BountyEndedData {
  reason: 'completed' | 'incorrect' | 'timeout' | 'violation';
  newRole: 'elite' | 'challenger';
}

interface SubmissionApiResponse {
  success: boolean;
  results?: SubmissionResult[];
  summary?: { passed: number; total: number };
  submission?: { status: string };
  message?: string;
}

interface EndPopupData {
  type: 'win' | 'lose' | 'timeout' | 'bounty-win' | 'bounty-fail' | 'bounty-timeout' | 'admin-end' | 'violation-forfeit' | 'opponent-violation';
  newRole: 'elite' | 'challenger';
}


// --- Helper Functions ---
const formatTime = (ms: number) => {
  if (ms <= 0) return "00:00";
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, '0');
  const seconds = (totalSeconds % 60).toString().padStart(2, '0');
  return `${minutes}:${seconds}`;
};

const formatTestCaseData = (data: unknown): string => {
  if (typeof data === 'string') return data;
  if (typeof data === 'object' && data !== null) return JSON.stringify(data, null, 2);
  return String(data);
};

export default function R2CodePage() {
  const router = useRouter();
  const { session } = useAuth();
  const { socket, isConnected } = useSocket();

  const [sessionData, setSessionData] = useState<SessionData | null>(null);
  const [timeRemaining, setTimeRemaining] = useState(0);
  const [pageIsLoading, setPageIsLoading] = useState(true);
  const sessionEndedRef = useRef(false);


  const [code, setCode] = useState("");
  const [language, setLanguage] = useState(() => {
    try { return localStorage.getItem('battlecode-round-2-language') || "python"; }
    catch { return "python"; }
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [sessionTerminated, setSessionTerminated] = useState(false);
  const [isRunning, setIsRunning] = useState(false);
  const [submissionResults, setSubmissionResults] = useState<SubmissionResult[] | null>(null);
  const [showHints, setShowHints] = useState(false);
  const [activeTab, setActiveTab] = useState<'testcases' | 'results'>('testcases');
  const [codeEditorHeight, setCodeEditorHeight] = useState(60);
  const [isDragging, setIsDragging] = useState(false);
  const [matchEnded, setMatchEnded] = useState(false);

  const [showEndPopup, setShowEndPopup] = useState(false);
  const [endPopupData, setEndPopupData] = useState<EndPopupData | null>(null);

  const [currentContext, setCurrentContext] = useState<CodeContext | null>(null);
  const [showBountySubmitModal, setShowBountySubmitModal] = useState(false);

  const codeRef = useRef(code);
  const saveTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const editorRef = useRef<monaco.editor.IStandaloneCodeEditor | null>(null);

  function handleEditorMount(
    editor: monaco.editor.IStandaloneCodeEditor,
    monacoInstance: typeof import('monaco-editor')
  ) {
    editorRef.current = editor;
    // Disable paste via context menu
    editor.addAction({
      id: "disable-paste",
      label: "Paste",
      keybindings: [],
      precondition: "false",
      run: () => { }
    });
    // Block DOM paste events
    const domNode = editor.getDomNode();
    if (domNode) {
      domNode.addEventListener("paste", (e: ClipboardEvent) => { // Fixed with the specific event type
        e.preventDefault();
        showErrorToast("Paste is disabled");
      }, true);
    }
    // Block keyboard shortcut Ctrl/Cmd+V
    editor.addCommand(monacoInstance.KeyMod.CtrlCmd | monacoInstance.KeyCode.KeyV, () => {
      showErrorToast("Paste shortcut is disabled");
    });
  }


  useEffect(() => { codeRef.current = code; }, [code]);
  useEffect(() => {
    try { localStorage.setItem('battlecode-round-2-language', language); } catch (e) { console.error("Could not save language to localStorage.", e); }
  }, [language]);

  const contextManager = useMemo(() => ({
    getStorageKey: () => `battlecode-round-2-code-store`,
    generateContextKey: (qId: string, lang: string) => `2:${qId}:${lang}`,
    loadCodeStore: (): CodeStore => {
      try { const stored = localStorage.getItem(contextManager.getStorageKey()); return stored ? JSON.parse(stored) : {}; }
      catch { return {}; }
    },
    saveCodeStore: (store: CodeStore) => {
      try { localStorage.setItem(contextManager.getStorageKey(), JSON.stringify(store)); return true; }
      catch { return false; }
    },
    getBoilerplate: (p: SessionData['question'] | null, lang: string) => p?.boilerplate?.[lang] || '',
    createContext: (qId: string, lang: string): CodeContext => ({ round: '2', questionId: qId, language: lang }),
    getCodeForContext: (store: CodeStore, context: CodeContext) => store[contextManager.generateContextKey(context.questionId, context.language)] || '',
    setCodeForContext: (store: CodeStore, context: CodeContext, newCode: string) => {
      const key = contextManager.generateContextKey(context.questionId, context.language);
      return { ...store, [key]: newCode };
    }
  }), []);

  const scheduleAutoSave = useCallback(() => {
    if (!currentContext || !codeRef.current) return;
    const codeToSave = codeRef.current;
    if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);

    saveTimeoutRef.current = setTimeout(() => {
      const currentStore = contextManager.loadCodeStore();
      const updatedStore = contextManager.setCodeForContext(currentStore, currentContext, codeToSave);
      contextManager.saveCodeStore(updatedStore);
    }, 1000);
  }, [currentContext, contextManager]);

  useEffect(() => {
    if (code && currentContext) {
      scheduleAutoSave();
    }
  }, [code, currentContext, scheduleAutoSave]);

  useEffect(() => {
    if (!sessionData?.question) return;

    const loadedStore = contextManager.loadCodeStore();
    const newContext = contextManager.createContext(sessionData.question.id, language);
    setCurrentContext(newContext);

    const savedCode = contextManager.getCodeForContext(loadedStore, newContext);
    const boilerplate = contextManager.getBoilerplate(sessionData.question, language);
    setCode(savedCode || boilerplate);

  }, [sessionData, language, contextManager]);

  const executeCode = useCallback(async (isFinalSubmission: boolean) => {
    if (!sessionData || (isSubmitting || isRunning)) return;
    const action = isFinalSubmission ? 'Submitting' : 'Running';
    const actionVerb = isFinalSubmission ? 'submit' : 'run';

    if (isFinalSubmission) setIsSubmitting(true); else setIsRunning(true);

    setSubmissionResults(null);
    setActiveTab('results');
    showInfoToast(`${action} for judging...`);

    const endpoint = `/api/submit/${actionVerb}`;
    try {
      const response = await fetch(`${process.env.NEXT_PUBLIC_API_URL}${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session?.access_token}` },
        body: JSON.stringify({
          language,
          source_code: code,
          problemId: sessionData.question.id,
          roundNumber: 2,
          context: {
            type: sessionData.type,
            contextId: sessionStorage.getItem('r2_context_id')
          }
        })
      });
      const result: SubmissionApiResponse = await response.json();
      if (result.success) {
        setSubmissionResults(result.results || []);
        const summary = result.summary || { passed: 0, total: (result.results || []).length };

        if (isFinalSubmission) {
          if (result.submission?.status !== 'ACCEPTED') {
            showErrorToast(`${summary.passed}/${summary.total} test cases passed.`);
          } else {
            showSuccessToast('All test cases passed!');
            socket?.emit("round2:matchEnd");
          }
        } else {
          showInfoToast(`Test run completed: ${summary.passed}/${summary.total} passed`);
        }
      } else { throw new Error(result.message || 'Request failed'); }
    } catch (error) {
      showErrorToast(`Failed to ${actionVerb}: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      if (isFinalSubmission) setIsSubmitting(false); else setIsRunning(false);
    }
  }, [sessionData, isSubmitting, isRunning, session?.access_token, language, code]);

  const monaco = useMonaco();
  const getMonacoLanguage = (lang: string) => {
    const languageMap: { [key: string]: string } = {
      'python': 'python',
      'java': 'java',
      'cpp': 'cpp',
      'c': 'c',

    };
    return languageMap[lang] || 'python';
  };
  useEffect(() => {
    monaco?.editor.defineTheme('custom-dark', {
      base: 'vs-dark', inherit: true, rules: [],
      colors: { 'editor.background': '#0a0a0a', 'editor.foreground': '#ffffff', 'editor.lineHighlightBackground': '#1a1a1a', 'editor.selectionBackground': '#264f78', 'editorCursor.foreground': '#f97316', 'editorLineNumber.foreground': '#858585', 'editorLineNumber.activeForeground': '#f97316' },
    });
    monaco?.editor.setTheme('custom-dark');
  }, [monaco]);
  const editorOptions = { minimap: { enabled: false }, fontSize: 14, scrollBeyondLastLine: false, automaticLayout: true, wordWrap: 'on' as const };

  const handleMouseDown = (e: React.MouseEvent) => { setIsDragging(true); e.preventDefault(); };
  const handleMouseUp = useCallback(() => setIsDragging(false), []);
  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging) return;
    const container = document.querySelector('.code-results-container') as HTMLElement;
    if (!container) return;
    const rect = container.getBoundingClientRect();
    const newHeight = Math.max(20, Math.min(80, ((e.clientY - rect.top) / rect.height) * 100));
    setCodeEditorHeight(newHeight);
  }, [isDragging]);

  useEffect(() => {
    if (monaco && editorRef.current) {
      let internalClipboard = "";
      const editor = editorRef.current;

      // intercept copy
      editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyC, () => {
        const sel = editor.getSelection();
        if (sel) {
          const selection = editor.getModel()?.getValueInRange(sel);
          if (selection) {
            internalClipboard = selection;
          }
        }
      });

      // intercept cut
      editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyX, () => {
        const sel = editor.getSelection();
        if (sel) {
          const selection = editor.getModel()?.getValueInRange(sel);
          if (selection) {
            internalClipboard = selection;
            editor.executeEdits("cut", [
              { range: sel, text: "", forceMoveMarkers: true },
            ]);
          }
        }
      });

      // intercept paste
      editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyV, () => {
        const sel = editor.getSelection();
        if (internalClipboard && sel) {
          editor.executeEdits("paste", [
            { range: sel, text: internalClipboard, forceMoveMarkers: true },
          ]);
        }
      });

      // disable right-click menu
      editor.updateOptions({ contextmenu: false });
    }
  }, [monaco]);



  useEffect(() => {
    if (isDragging) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'row-resize';
      document.body.style.userSelect = 'none';
    } else {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    }
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  // --- FIX: Wrapped triggerSessionEnd in useCallback ---
  const triggerSessionEnd = useCallback((type: EndPopupData['type'], newRole: 'elite' | 'challenger') => {
    if (!newRole) {
      console.error("TriggerSessionEnd called without a new role. Aborting popup.");
      showErrorToast("Could not determine next step. Redirecting to dashboard.");
      const userRole =
        (sessionStorage.getItem('r2_user_role') as 'elite' | 'challenger') ||
        'challenger';
      router.push(`/r2/${userRole}`);
      return;
    }
    sessionStorage.removeItem('r2_session_type');
    sessionStorage.removeItem('r2_context_id');
    sessionStorage.setItem('r2_user_role', newRole);
    setEndPopupData({ type, newRole });
    setShowEndPopup(true);
  }, [router]);


  const safeTriggerSessionEnd = useCallback(
    (type: EndPopupData['type'], newRole: 'elite' | 'challenger') => {
      if (sessionEndedRef.current) return;

      sessionEndedRef.current = true;
      triggerSessionEnd(type, newRole);
    },
    [triggerSessionEnd]
  );


  // --- Socket Event Handlers ---
  const handleTimerUpdate = useCallback((data: { timeRemaining: number }) => {
    const remaining = data.timeRemaining * 1000; // Convert to milliseconds
    setTimeRemaining(remaining);

    // Warn user when time is low
    if (data.timeRemaining <= 60 && data.timeRemaining > 0) {
      showErrorToast(`Only ${data.timeRemaining} seconds remaining!`);
    }

    // Auto-submit when time is up
    if (data.timeRemaining <= 0) {
      showErrorToast("Time's up. Waiting for server decision...");
    }
  }, [sessionData?.type, triggerSessionEnd]);

  const handleAdminRemoved = useCallback(() => {
    showErrorToast('You have been removed from Round 2 by an admin');
    sessionStorage.removeItem('r2_session_type');
    sessionStorage.removeItem('r2_context_id');
    sessionStorage.removeItem('r2_user_role');
    router.push('/dashboard');
  }, [router]);

  const handleAdminAdded = useCallback(() => {
    showSuccessToast('You have been added back to Round 2 by an admin');
    // Reload the page to get fresh state
    router.refresh();
  }, [router]);

  const handleState = useCallback((data: GetStateResponse) => {
    if (!data.success) return;

    if (data.sessionData) {
      setSessionData(prev => prev ? { ...prev, ...data.sessionData } : (data.sessionData ?? null));
    }

    if (typeof data.globalTimeRemaining === "number") {
      setTimeRemaining(data.globalTimeRemaining * 1000); // Convert to milliseconds
    }
  }, []);

  useEffect(() => {
    if (!sessionData?.endTime || showEndPopup) return;

    const timerInterval = setInterval(() => {
      const remaining = sessionData.endTime - Date.now();

      if (remaining <= 0) {
        setTimeRemaining(0);
        clearInterval(timerInterval);



        showErrorToast("Time's up. Waiting for server decision...");
      } else {
        setTimeRemaining(remaining);
      }
    }, 1000);

    return () => clearInterval(timerInterval);
    // --- FIX: Added triggerSessionEnd to dependency array ---
  }, [sessionData, showEndPopup, triggerSessionEnd]);

  // Initial state fetch
  useEffect(() => {
    if (!socket || !isConnected) return;

    const sessionType = sessionStorage.getItem('r2_session_type');
    const contextId = sessionStorage.getItem('r2_context_id');
    const userRole = sessionStorage.getItem('r2_user_role') || '';

    if (!sessionType || !contextId) {
      showErrorToast("Session context is missing. Returning.");
      router.push(userRole ? `/r2/${userRole}` : '/dashboard');
      return;
    }

    socket.emit('round2:getCodePageState', { contextId, sessionType }, (response: GetCodePageStateResponse) => {
      if (response.success && response.sessionData) {
        setSessionData(response.sessionData);
      } else {
        showErrorToast(response.message || "Could not load session data.");
        router.push(`/r2/${userRole}`);
      }
      setPageIsLoading(false);
    });
  }, [socket, isConnected, router]);

  useEffect(() => {
    if (!socket || !session?.user?.email) return;

    const handleRound2Redirect = ({
      target,
      reason,
    }: {
      target: string;
      reason?: string;
    }) => {
      console.log("[ROUND2 REDIRECT]", { target, reason });

      showErrorToast(reason || "You were removed from Round 2");

      // hard reset local session
      sessionStorage.removeItem("r2_session_type");
      sessionStorage.removeItem("r2_context_id");
      sessionStorage.removeItem("r2_user_role");

      router.push("/r2" + target);
    };

    const handleMatchResult = (data: MatchResultData) => {
      const isWinner = data.winnerId === session.user.email;

      let type: EndPopupData['type'];

      if (data.reason === 'violation') {
        type = isWinner ? 'opponent-violation' : 'violation-forfeit';
      } else if (data.reason === 'timeout') {
        type = 'timeout';
      } else {
        type = isWinner ? 'win' : 'lose';
      }

      safeTriggerSessionEnd(type, data.newRole);
    };


    const handleBountyEnded = (data: BountyEndedData) => {
      let type: EndPopupData['type'];

      if (data.reason === 'violation') {
        type = 'violation-forfeit';
      } else if (data.reason === 'timeout') {
        type = 'bounty-timeout';
      } else if (data.reason === 'completed') {
        type = 'bounty-win';
      } else {
        type = 'bounty-fail';
      }

      safeTriggerSessionEnd(type, data.newRole);
    };


    const handleRoundEnd = () => {
      showInfoToast("Round 2 has ended. You will be redirected to the dashboard.");
      sessionStorage.removeItem('r2_session_type');
      sessionStorage.removeItem('r2_context_id');
      setTimeout(() => {
        router.push('/dashboard');
      }, 3000);
    };

    const handleViolationForfeit = () => {
      console.warn("round2:violationForfeit received");

      const userRole =
        (sessionStorage.getItem('r2_user_role') as 'elite' | 'challenger') ||
        'challenger';

      safeTriggerSessionEnd('violation-forfeit', userRole);
    };


    const handleOpponentViolated = () => {
      console.warn("round2:opponentViolated received");

      const userRole =
        (sessionStorage.getItem('r2_user_role') as 'elite' | 'challenger') ||
        'challenger';

      safeTriggerSessionEnd('opponent-violation', userRole);
    };


    socket.on('round2:matchResult', handleMatchResult);
    socket.on('round2:bountyEnded', handleBountyEnded);
    socket.on('round2:ended', handleRoundEnd);
    socket.on('round2:timerUpdate', handleTimerUpdate);
    socket.on('round2:adminRemoved', handleAdminRemoved);
    socket.on('round2:adminAdded', handleAdminAdded);
    socket.on("round2:redirect", handleRound2Redirect);

    return () => {
      socket.off("round2:redirect", handleRound2Redirect);
      socket.off('round2:matchResult', handleMatchResult);
      socket.off('round2:bountyEnded', handleBountyEnded);
      socket.off('round2:ended', handleRoundEnd);
      socket.off('round2:timerUpdate', handleTimerUpdate);
      socket.off('round2:adminRemoved', handleAdminRemoved);
      socket.off('round2:adminAdded', handleAdminAdded);
      socket.off('round2:violationForfeit', handleViolationForfeit);
      socket.off('round2:opponentViolated', handleOpponentViolated);
    };
    // --- FIX: Added triggerSessionEnd to dependency array ---
  }, [socket, router, session?.user?.email, triggerSessionEnd, handleTimerUpdate, handleAdminRemoved, handleAdminAdded]);

  // Request timer sync when socket and sessionData are available
  useEffect(() => {
    if (socket && sessionData && sessionData.question && !pageIsLoading) {
      // Request timer state from server
      socket.emit('round2:getTimerState', {
        questionId: sessionData.question.id,
        sessionType: sessionStorage.getItem('r2_session_type'),
        contextId: sessionStorage.getItem('r2_context_id')
      });

      // Set up periodic timer sync (every 30 seconds)
      const syncInterval = setInterval(() => {
        socket.emit('round2:getTimerState', {
          questionId: sessionData.question.id,
          sessionType: sessionStorage.getItem('r2_session_type'),
          contextId: sessionStorage.getItem('r2_context_id')
        });
      }, 30000);

      // Also request state update
      const stateInterval = setInterval(() => {
        socket.emit('round2:getState', {
          contextId: sessionStorage.getItem('r2_context_id'),
          sessionType: sessionStorage.getItem('r2_session_type')
        });
      }, 15000);

      return () => {
        clearInterval(syncInterval);
        clearInterval(stateInterval);
      };
    }
  }, [socket, sessionData, pageIsLoading]);

  // Listen for state updates
  useEffect(() => {
    if (!socket) return;

    socket.on("round2:state", handleState);
    socket.emit("round2:getState", {
      contextId: sessionStorage.getItem('r2_context_id'),
      sessionType: sessionStorage.getItem('r2_session_type')
    }); // request once on mount

    return () => {
      socket.off("round2:state", handleState);
    };
  }, [socket, handleState]);

  useEffect(() => {
    if (showEndPopup && endPopupData?.newRole) {
      const timer = setTimeout(() => {
        router.push(`/r2/${endPopupData.newRole}`);
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [showEndPopup, endPopupData, router]);


  if (pageIsLoading || !sessionData) {
    return <LoadingOverlay isLoading={true} message="Loading Session..." />;
  }

  const { question, type, opponent } = sessionData;

  const getPopupContent = (data: EndPopupData | null) => {
    if (!data) return null;
    switch (data.type) {
      case 'win': return { title: '≡ƒÄë Victory!', message: `You defeated your opponent! Your new role is ${data.newRole}.`, className: 'text-green-400' };
      case 'lose': return { title: '≡ƒÿö Defeat', message: `You were defeated. Your new role is ${data.newRole}.`, className: 'text-red-400' };
      case 'timeout': return { title: "ΓÅ░ Time's Up!", message: 'The match ended. You will now be redirected.', className: 'text-yellow-400' };
      case 'bounty-win': return { title: '≡ƒÅå Bounty Claimed!', message: `You solved the bounty! Your new role is ${data.newRole}.`, className: 'text-green-400' };
      case 'bounty-fail': return { title: '≡ƒÆí Attempt Logged', message: 'Your solution was incorrect. You will be redirected.', className: 'text-yellow-400' };
      case 'bounty-timeout': return { title: "ΓÅ│ Time's Up!", message: 'Your bounty attempt timed out. You will be redirected.', className: 'text-yellow-400' };
      case 'admin-end': return { title: '≡ƒ¢æ Session Ended', message: 'The session was ended by an admin. You will be redirected.', className: 'text-orange-400' };
      case 'violation-forfeit': return { title: '≡ƒÜ½ Disqualified', message: 'You have been forfeited from this session due to multiple rule violations.', className: 'text-red-500 font-bold' };
      case 'opponent-violation': return { title: '≡ƒÜ⌐ Opponent Disqualified', message: 'Your opponent committed a violation. You have been awarded the win!', className: 'text-green-400 font-bold' };
      default: return null;
    }
  };

  const popupContent = getPopupContent(endPopupData);


  return (
    <SecureWrapper>
      <div className="flex flex-col h-screen text-white overflow-hidden bg-[url('/bg-code.svg')] bg-fixed bg-cover bg-center oxanium">
        <div className="flex-1 flex p-4 gap-4 bg-black/40 min-h-0">
          <CustomScrollbar className="w-1/2 flex border rounded-lg border-amber-600 bg-black/40 p-4 flex-col min-h-0 overflow-hidden glass-box">
            <div className="flex justify-between items-start mb-4 flex-shrink-0">
              <div>
                <h2 className="text-2xl font-bold">{question.title}</h2>
                <div className="flex gap-4 text-sm text-gray-400 mt-1">
                  {/* <span>Difficulty: {question.difficulty}</span> */}
                  {type === 'match' && opponent && <span>vs {opponent.username}</span>}
                  {type === 'bounty' && <span>Bounty Challenge</span>}
                </div>
              </div>
              {question.hints && question.hints.length > 0 && (
                <button onClick={() => setShowHints(!showHints)} className="rounded-lg border p-4 h-12 text-white border-amber-600 font-oxanium w-30 justify-center items-center flex bg-black/20 backdrop-blur-sm hover:bg-amber-600 hover:text-black transition-colors duration-300 gap-2">
                  <Lightbulb className="h-4 w-4" /> {showHints ? "Hide" : "Hint"}
                </button>
              )}
            </div>
            <div className="flex-1 overflow-y-auto min-h-0 pr-2">
              {showHints && question.hints && question.hints.length > 0 && (
                <div className="mb-4 bg-black p-3 rounded"><h3 className="font-bold mb-2 text-amber-400">Hints:</h3><ul className="list-disc list-inside text-gray-300 space-y-2">{question.hints.map((hint, i) => <li key={i}>{hint}</li>)}</ul></div>
              )}
              <p className="mb-4 text-gray-300 whitespace-pre-wrap">{question.description}</p>
              {question.constraints && question.constraints.length > 0 && (
                <><h3 className="font-bold mb-2 text-amber-400">Constraints:</h3><ul className="list-disc list-inside mb-4 text-gray-300 font-mono text-sm">{question.constraints.map((c, i) => <li key={i}>{c}</li>)}</ul></>
              )}
              {question.sampleTestCases && question.sampleTestCases.length > 0 && (
                <><h3 className="font-bold mb-4 text-amber-400">Sample Cases:</h3>
                  {question.sampleTestCases.map((tc, i) => (
                    <div key={i} className="mb-4 bg-black/20 border-amber-600/50 mr-2 border-2 p-3 rounded font-mono text-sm">
                      <p className="font-bold text-gray-400">Input:</p><pre className="bg-gray-800/60 p-2 rounded mt-1 whitespace-pre-wrap">{formatTestCaseData(tc.stdin || tc.input?.stdin || tc.input?.json || '')}</pre>
                      <p className="mt-2 font-bold text-gray-400">Output:</p><pre className="bg-gray-800/60 p-2 rounded mt-1 whitespace-pre-wrap">{formatTestCaseData(tc.expected_output || tc.output?.stdout || tc.output?.json || '')}</pre>
                      {tc.explanation && <p className="mt-2 text-xs text-gray-400 italic">Explanation: {tc.explanation}</p>}
                    </div>
                  ))}</>
              )}
            </div>
          </CustomScrollbar>
          <div className="w-1/2 flex flex-col code-results-container gap-1">
            <div className="border border-amber-600 rounded-lg p-4 flex flex-col min-h-0 glass-box" style={{ height: `${codeEditorHeight}%` }}>
              <div className="flex justify-between items-center mb-2 gap-2">
                <select value={language} onChange={(e) => setLanguage(e.target.value)} className="bg-black text-white p-2 rounded border w-32 border-amber-600 focus:outline-none focus:ring-2 focus:ring-amber-500">
                  <option value="python">Python</option><option value="java">Java</option>
                  <option value="cpp">C++</option><option value="C">C</option>
                </select>
                <div className={`text-center p-2 font-mono text-xl bg-gray-800 rounded border border-amber-600 ${timeRemaining <= 60000 ? 'text-red-400 animate-pulse' : ''}`}>
                  {formatTime(timeRemaining)}
                </div>
                <div className="flex-1 flex justify-end items-center gap-2">
                  <button onClick={() => executeCode(false)} disabled={isRunning || isSubmitting} className="flex items-center bg-black text-white p-2 rounded border border-amber-600 hover:bg-amber-600 hover:text-black transition-colors disabled:opacity-50"><span className="pl-2">Run</span><Play className="ml-2 h-4 w-4" /></button>
                  <button onClick={() => {
                    if (sessionData.type === 'bounty') {
                      setShowBountySubmitModal(true);
                      socket?.emit("round2:bountyend");
                    } else {
                      executeCode(true);
                    }
                  }}
                    disabled={isSubmitting || isRunning}
                  >
                    <p className="pl-2">{isSubmitting ? "Submitting..." : "Submit"}</p>
                    <Image src="/submit_2.png" alt="submit" width={16} height={16} className="mr-2" />
                  </button>

                </div>
              </div>
              <div className="flex-1 rounded overflow-hidden border border-gray-700">
                <Editor
                  height="100%"
                  language={getMonacoLanguage(language)}
                  value={code}
                  onChange={(value) => setCode(value || "")}
                  theme="custom-dark"
                  options={editorOptions}
                  onMount={handleEditorMount}
                  loading={
                    <div className="flex items-center justify-center h-full bg-black">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
                    </div>
                  }
                />
              </div>
            </div>
            <div onMouseDown={handleMouseDown} className={`h-1 bg-amber-600/20 hover:bg-amber-600/40 cursor-row-resize transition-colors flex items-center justify-center ${isDragging ? 'bg-amber-600/60' : ''}`}><div className="w-8 h-1 bg-amber-600 rounded-full"></div></div>
            <div className="border border-amber-600 rounded-lg p-4 flex flex-col glass-box" style={{ height: `${100 - codeEditorHeight}%` }}>
              <div className="flex border-b border-amber-600/30 mb-3 flex-shrink-0">
                <button onClick={() => setActiveTab('testcases')} className={`px-4 py-2 font-medium ${activeTab === 'testcases' ? 'border-b-2 border-amber-500 text-amber-400' : 'text-gray-400'}`}>Test Cases</button>
                <button onClick={() => setActiveTab('results')} className={`px-4 py-2 font-medium ${activeTab === 'results' ? 'border-b-2 border-amber-500 text-amber-400' : 'text-gray-400'}`}>Test Results {submissionResults && <span className="ml-2 text-xs bg-amber-600 text-black px-2 py-1 rounded-full">{submissionResults.length}</span>}</button>
              </div>
              <div className="flex-1 min-h-0">
                <CustomScrollbar className="h-full overflow-y-auto">
                  {activeTab === 'testcases' && (
                    <div className="space-y-3 pr-2">
                      {question.sampleTestCases?.length ? question.sampleTestCases.map((tc, i) => (
                        <div key={i} className="border border-gray-600 rounded-lg p-3 bg-black/20">
                          <h4 className="font-semibold text-amber-400">Case {i + 1}</h4>
                          <div className="space-y-2 mt-2">
                            <div><p className="text-sm font-medium text-gray-300 mb-1">Input:</p><pre className="bg-gray-800/60 p-2 rounded text-sm font-mono overflow-x-auto border border-gray-700">{formatTestCaseData(tc.stdin || tc.input?.stdin || tc.input?.json || '')}</pre></div>
                            <div><p className="text-sm font-medium text-gray-300 mb-1">Expected Output:</p><pre className="bg-gray-800/60 p-2 rounded text-sm font-mono overflow-x-auto border border-gray-700">{formatTestCaseData(tc.expected_output || tc.output?.stdout || tc.output?.json || '')}</pre></div>
                          </div>
                        </div>
                      )) : <div className="text-center text-gray-400 py-8"><p>No sample test cases.</p></div>}
                    </div>
                  )}
                  {activeTab === 'results' && (
                    <div className="pr-2">
                      {(isRunning || isSubmitting) && !submissionResults && <div className="flex items-center justify-center h-full"><div className="flex items-center gap-2 text-amber-400"><div className="animate-spin rounded-full h-5 w-5 border-b-2 border-amber-500"></div><span>Processing...</span></div></div>}
                      {submissionResults?.length ? (
                        <div className="space-y-2">
                          {submissionResults.map((res, i) => {
                            const isAccepted = res.status.description === "Accepted";
                            return (
                              <div key={res.token || i} className={`p-3 rounded border ${isAccepted ? "bg-green-800/30 border-green-600/50" : "bg-red-800/30 border-red-600/50"}`}>
                                <div className="flex items-center justify-between mb-2"><p className="font-bold">Test Case {i + 1}</p><span className={`text-sm font-medium px-2 py-1 rounded ${isAccepted ? "text-green-400 bg-green-900/50" : "text-red-400 bg-red-900/50"}`}>{res.status.description}</span></div>

                                {/* Display stdout if available */}
                                {res.stdout && (
                                  <div className="mt-2">
                                    <p className="text-xs font-semibold text-gray-300 mb-1">Output:</p>
                                    <pre className="text-xs text-gray-200 whitespace-pre-wrap bg-black/40 p-2 rounded border border-gray-600 max-h-32 overflow-y-auto">{res.stdout}</pre>
                                  </div>
                                )}

                                {!isAccepted && (res.stderr || res.compile_output) && (
                                  <div className="mt-2">
                                    <p className="text-xs font-semibold text-red-300 mb-1">Error:</p>
                                    <pre className="text-xs text-red-300 whitespace-pre-wrap bg-black/50 p-2 rounded border border-gray-700 overflow-x-auto max-h-32 overflow-y-auto">{res.stderr || res.compile_output}</pre>
                                  </div>
                                )}

                                {res.time && <div className="flex gap-4 text-xs text-gray-400 mt-2"><span>Runtime: {res.time}s</span><span>Memory: {res.memory}KB</span></div>}
                              </div>
                            );
                          })}
                        </div>
                      ) : !isRunning && !isSubmitting && (<div className="text-center text-gray-400 py-8"><p>Run or submit code to see results</p></div>)}
                    </div>
                  )}
                </CustomScrollbar>
              </div>
            </div>
          </div>
        </div>
      </div>
      {showEndPopup && popupContent && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-gray-800 p-8 rounded-lg border-2 border-orange-500 text-center max-w-md">
            <h2 className={`text-3xl font-bold mb-4 ${popupContent.className}`}>
              {popupContent.title}
            </h2>
            <p className="text-white text-lg mb-6">
              {popupContent.message}
            </p>
            <p className="text-sm text-gray-400">
              Redirecting in 5 seconds...
            </p>
          </div>
        </div>
      )}

      {showBountySubmitModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-gray-900 border-2 border-amber-600 rounded-lg p-6 max-w-md w-full text-center">
            <h2 className="text-2xl font-bold text-amber-400 mb-4">
              Final Submission
            </h2>

            <p className="text-gray-300 mb-6">
              This is a <span className="text-amber-400 font-semibold">Bounty Challenge</span>.
              <br />
              You only get <span className="text-red-400 font-semibold">one submission</span>.
              <br />
              Submitting now will immediately end the bounty.
            </p>

            <div className="flex justify-center gap-4">
              <button
                onClick={() => setShowBountySubmitModal(false)}
                className="px-4 py-2 rounded border border-gray-600 text-gray-300 hover:bg-gray-800"
              >
                Cancel
              </button>

              <button
                onClick={() => {
                  setShowBountySubmitModal(false);
                  executeCode(true);
                }}
                className="px-4 py-2 rounded bg-amber-600 text-black font-semibold hover:bg-amber-500"
              >
                Submit Anyway
              </button>
            </div>
          </div>
        </div>
      )}

    </SecureWrapper>
  );
}

