"use client"
import { useAuth } from "@/contexts/AuthContext";
import Image from "next/image";
import CustomScrollbar from "./CustomScrollbar";
import { useEffect, useState, useCallback } from "react";

interface LobbyPageProps {
  round: string;
  participants: Array<{
    userId: string;
    username: string;
    status: 'WAITING' | 'IN_MATCH' | 'DISCONNECTED' | 'FINISHED';
    joinedAt: string;
    isReady: boolean;
    disconnectedAt?: string;
    reconnectedAt?: string;
    finishedAt?: string;
  }>;
  isRoundActive: boolean;
  timeRemaining: number;
  roundDuration: number;
  totalParticipants: number;
  isLoading: boolean;
  roundStarted: boolean;
  onStartRound?: () => void;
  onJoinRound?: () => void;
}

export default function Waiting({ 
  round, 
  participants, 
  isRoundActive, 
  timeRemaining, 
  roundDuration, 
  totalParticipants, 
  isLoading, 
  roundStarted,
  onStartRound,
  onJoinRound
}: LobbyPageProps) {
  const { user, userRole } = useAuth();
  
  // Check if current user is admin
  const isAdmin = userRole === 'ADMIN';

  // State for animated bubbles
  const [bubbles, setBubbles] = useState<Array<{
    id: number;
    initials: string;
    x: number;
    y: number;
    size: number;
    speed: number;
    opacity: number;
    color: string;
  }>>([]);

  // Get initials from username
  const getInitials = (username: string): string => {
    const words = username.trim().split(/\s+/);
    if (words.length >= 2) {
      return (words[0][0] + words[1][0]).toUpperCase();
    } else if (words.length === 1 && words[0].length >= 2) {
      return words[0].substring(0, 2).toUpperCase();
    } else {
      return (words[0][0] + (words[0][1] || '')).toUpperCase();
    }
  };

  // Colors for bubbles
  /*const bubbleColors = [
    'rgba(249, 115, 22, 0.7)', // orange
    'rgba(59, 130, 246, 0.7)', // blue
    'rgba(16, 185, 129, 0.7)', // emerald
    'rgba(139, 92, 246, 0.7)', // violet
    'rgba(236, 72, 153, 0.7)', // pink
    'rgba(245, 158, 11, 0.7)', // amber
    'rgba(20, 184, 166, 0.7)', // teal
    'rgba(239, 68, 68, 0.7)',  // red
  ];*/

  // Create new bubble
  const createBubble = useCallback(() => {
    if (participants.length === 0) return;
    
    const randomParticipant = participants[Math.floor(Math.random() * participants.length)];
    const initials = getInitials(randomParticipant.username);
    
    return {
      id: Date.now() + Math.random(),
      initials,
      x: Math.random() * 70, // limit to left 70% to avoid leaderboard area
      y: 110, // start below screen
      size: 40 + Math.random() * 40, // 40-80px
      speed: 0.5 + Math.random() * 1, // 0.5-1.5% per frame
      opacity: 0.3 + Math.random() * 0.4, // 0.3-0.7
      color: 'rgba(239, 68, 68, 0.1)' // very transparent red
    };
  }, [participants]);

  // Animation loop
  useEffect(() => {
    if (participants.length === 0) return;

    const interval = setInterval(() => {
      setBubbles(prevBubbles => {
        let newBubbles = [...prevBubbles];
        
        // Update existing bubbles
        newBubbles = newBubbles
          .map(bubble => ({
            ...bubble,
            y: bubble.y - bubble.speed,
            // Start fading out when bubble reaches top 10% of screen
            opacity: bubble.y < 10 ? bubble.opacity * 0.95 : bubble.opacity
          }))
          // Remove bubbles when they go off screen at the top
          .filter(bubble => bubble.y > -10);
        
        // Add new bubble occasionally
        if (Math.random() < 0.3 && newBubbles.length < 15) {
          const newBubble = createBubble();
          if (newBubble) {
            newBubbles.push(newBubble);
          }
        }
        
        return newBubbles;
      });
    }, 100); // 10fps

    return () => clearInterval(interval);
  }, [participants, createBubble]);

  // Clear bubbles when participants change
  useEffect(() => {
    if (participants.length === 0) {
      setBubbles([]);
    }
  }, [participants.length]);

  // Format time display
  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  // Get status color for participants
  const getStatusColor = (status: string): string => {
    switch (status) {
      case 'WAITING': return 'text-yellow-400';
      case 'IN_MATCH': return 'text-green-400';
      case 'DISCONNECTED': return 'text-red-400';
      case 'FINISHED': return 'text-blue-400';
      default: return 'text-gray-400';
    }
  };

  // Get status display text
  const getStatusText = (status: string): string => {
    switch (status) {
      case 'WAITING': return 'Waiting';
      case 'IN_MATCH': return 'Playing';
      case 'DISCONNECTED': return 'Disconnected';
      case 'FINISHED': return 'Finished';
      default: return status;
    }
  };

  return (
    <>
      <div className="flex bg-[url('/bg_code.png')] bg-cover h-screen flex-col overflow-hidden relative">
        {/* Animated Background Bubbles - floating to the top but avoiding leaderboard */}
        <div className="absolute inset-0 pointer-events-none overflow-hidden">
          {bubbles.map(bubble => (
            <div
              key={bubble.id}
              className="absolute rounded-full flex items-center justify-center text-white font-bold text-sm transition-all duration-300 shadow-lg backdrop-blur-sm border border-white/20"
              style={{
                left: `${bubble.x}%`,
                top: `${bubble.y}%`,
                width: `${bubble.size}px`,
                height: `${bubble.size}px`,
                backgroundColor: bubble.color,
                opacity: bubble.opacity,
                fontSize: `${bubble.size * 0.3}px`,
                transform: 'translateX(-50%) translateY(-50%)',
                zIndex: 1
              }}
            >
              {bubble.initials}
            </div>
          ))}
        </div>

        <div className="flex-shrink-0 ml-3 mt-0 py-4 relative z-10 orbitron">
          <p> {"<> BattleCode Arena"}</p>
        </div>
        <div className="flex-1 flex min-h-0 relative z-10">
          <div className="flex-[1]"></div>
          <div className="flex-[6] flex justify-center items-center gap-4 flex-col min-h-0">
            {!isRoundActive && !roundStarted ? (
              <>
                <div className="text-5xl text-center bg-gradient-to-r from-[#EEA284] to-[#FF6200] bg-clip-text text-transparent">Searching for opponent</div>
                <div className="text-gray-200 text-center">
                  {participants.length > 0 ? (
                    <div>
                      <p>Waiting for participants to join...</p>
                      <p className="text-orange-400 font-bold mt-2">{totalParticipants} participants ready</p>
                    </div>
                  ) : (
                    <p>Connecting to lobby...</p>
                  )}
                  
                  {!isLoading && (
                    <div className="flex justify-center items-center gap-2 mt-4">
                      <div className="bg-orange-500 rounded-full h-4 w-4 animate-pulse"></div>
                      <div className="bg-orange-500 rounded-full h-4 w-4 animate-pulse" style={{animationDelay: '0.5s'}}></div>
                      <div className="bg-orange-500 rounded-full h-4 w-4 animate-pulse" style={{animationDelay: '1s'}}></div>
                    </div>
                  )}
                </div>

                {/* Admin Start Button */}
                {isAdmin && !isLoading && totalParticipants > 0 && onStartRound && (
                  <button
                    onClick={onStartRound}
                    className="mt-6 px-8 py-3 bg-gradient-to-r from-orange-500 to-amber-600 text-white font-bold rounded-lg shadow-lg hover:scale-105 transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-amber-400"
                    disabled={isLoading}
                  >
                    ≡ƒÜÇ Start Round {round} (Admin)
                  </button>
                )}
              </>
            ) : roundStarted ? (
              <>
                <div className="text-4xl text-center text-green-400">Round {round} Started!</div>
                <div className="text-gray-200 text-center">
                  <p>Redirecting to coding environment...</p>
                  <div className="flex justify-center items-center gap-2 mt-4">
                    <div className="bg-green-500 rounded-full h-4 w-4 animate-pulse"></div>
                    <div className="bg-green-500 rounded-full h-4 w-4 animate-pulse" style={{animationDelay: '0.5s'}}></div>
                    <div className="bg-green-500 rounded-full h-4 w-4 animate-pulse" style={{animationDelay: '1s'}}></div>
                  </div>
                </div>
              </>
            ) : (
              <>
                <div className="text-4xl text-center text-green-400">Round {round} Active</div>
                <div className="text-gray-200 text-center">
                  <p>Round is currently in progress</p>
                  <p className="text-orange-400 font-bold mt-2">Time Remaining: {formatTime(timeRemaining)}</p>
                  {onJoinRound && (
                    <button
                      onClick={onJoinRound}
                      className="mt-4 px-6 py-2 bg-gradient-to-r from-blue-500 to-purple-600 text-white font-bold rounded-lg shadow-lg hover:scale-105 transition-all duration-300"
                    >
                      Join Round
                    </button>
                  )}
                </div>
              </>
            )}
          </div>
          <div className="flex-[3] flex flex-col min-h-0">

            <div className="flex-1 max-h-full rounded-lg border-2 mb-4 mr-8 flex flex-col glass-box overflow-hidden">
              <div className="flex-shrink-0 bg-inherit rounded-t-lg z-10 justify-center items-center flex py-4">
                <Image src="/leaderboard-img.svg" alt="Leaderboard Icon" className="w-4 h-4 mr-2" width={16} height={16} />
                <p className="text-2xl text-orange-500">Round {round} Participants</p>
              </div>
              <CustomScrollbar className="flex-1 overflow-y-auto px-4 pb-4 min-h-0">
                {participants.length > 0 ? (
                  <table className="w-full text-left text-sm text-white">
                    <thead>
                      <tr className="border-b border-gray-700">
                        <th className="py-2 px-3 font-bold">#</th>
                        <th className="py-2 px-3 font-bold">Player</th>
                        <th className="py-2 px-3 font-bold">Status</th>
                        <th className="py-2 px-3 font-bold">Joined</th>
                      </tr>
                    </thead>
                    <tbody>
                      {participants.map((participant, idx) => (
                        <tr key={participant.userId} className="border-gray-800 hover:bg-white/5 transition">
                          <td className="py-2 px-3">{idx + 1}</td>
                          <td className="py-2 px-3 max-w-[120px] truncate">
                            {participant.username}
                            {participant.userId === user?.id && (
                              <span className="ml-2 text-orange-400 text-xs">(You)</span>
                            )}
                          </td>
                          <td className={`py-2 px-3 ${getStatusColor(participant.status)}`}>
                            {getStatusText(participant.status)}
                          </td>
                          <td className="py-2 px-3 text-xs text-gray-400">
                            {new Date(participant.joinedAt).toLocaleTimeString()}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : (
                  <div className="flex items-center justify-center h-full text-gray-400">
                    {isLoading ? (
                      <div className="flex items-center gap-2">
                        <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-orange-500"></div>
                        <span>Loading participants...</span>
                      </div>
                    ) : (
                      <p>No participants yet</p>
                    )}
                  </div>
                )}
              </CustomScrollbar>

            </div>

            {/* Round Info Panel */}
            <div className="flex-shrink-0 rounded-lg border-2 mr-8 glass-box p-4">
              <h3 className="text-lg font-bold text-orange-500 mb-2">Round Info</h3>
              <div className="text-sm text-gray-300 space-y-1">
                <p>Duration: {Math.floor(roundDuration / 60)} minutes</p>
                <p>Mode: Competitive</p>
                <p>Status: {isRoundActive ? 'Active' : 'Waiting'}</p>
                {timeRemaining > 0 && (
                  <p className="text-orange-400 font-bold">
                    Time Left: {formatTime(timeRemaining)}
                  </p>
                )}
              </div>
            </div>

          </div>
        </div>
      </div>
    </>
  )
}

"use client";
import { createBrowserClient } from "@supabase/ssr";
import { useRouter } from "next/navigation";
import { createContext, useContext, useEffect, useState } from "react";
import { User, Session } from "@supabase/supabase-js";

type AuthContextType = {
  user: User | null;
  session: Session | null;
  isLoading: boolean;
  avatarUrl: string | null;
  hasUsername: boolean | null;
  username: string | null;
  userName: string | null; // Added name from database
  userId: string | null;
  userRole: string | null;
  signInWithGoogle: () => Promise<void>;
  signOut: () => Promise<void>;
  updateUsername: (username: string) => Promise<boolean>;
};

const AuthContext = createContext<AuthContextType>(null!);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
  const [hasUsername, setHasUsername] = useState<boolean | null>(null);
  const [username, setUsername] = useState<string | null>(null);
  const [userName, setUserName] = useState<string | null>(null); // Added name state
  const [userId, setUserId] = useState<string | null>(null);
  const [userRole, setUserRole] = useState<string | null>(null);
  const supabase = createBrowserClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
  );
  const router = useRouter();

  useEffect(() => {
    const getSession = async () => {
      try {
        // Force clear any stuck sessions on initial load
        if (typeof window !== 'undefined') {
          const hasStuckSession = localStorage.getItem('stuck_session_detected');
          
          // Only clear if we explicitly marked a session as stuck, not just because we're on dashboard
          if (hasStuckSession === 'true') {
    
            await supabase.auth.signOut();
            localStorage.removeItem('stuck_session_detected');
            // Clear all auth-related storage
            Object.keys(localStorage).forEach(key => {
              if (key.startsWith('sb-') || key.startsWith('supabase') || key.includes('auth')) {
                localStorage.removeItem(key);
              }
            });
            setSession(null);
            setUser(null);
            setUserId(null);
            setHasUsername(null);
            setUsername(null);
            setUserName(null);
            setUserRole(null);
            setAvatarUrl(null);
            setIsLoading(false);
            return;
          }
        }

        const {
          data: { session },
        } = await supabase.auth.getSession();

        setSession(session);
        setUser(session?.user ?? null);
        setUserId(session?.user?.id ?? null);
        setAvatarUrl(session?.user?.user_metadata?.avatar_url ?? null);
        
        // Check username status if user is logged in
        if (session?.access_token) {
          setIsLoading(true); // Set loading during verification
          try {
            const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
            const response = await fetch(`${apiUrl}/api/user/verify`, {
              method: "POST",
              headers: {
                Authorization: `Bearer ${session.access_token}`,
              },
            }).catch((fetchError) => {
              console.error("Network error during initial verification:", fetchError);
              // Return a mock response object to handle network errors gracefully
              return { ok: false, status: 0, text: async () => 'Network error' } as Response;
            });

            if (response.ok) {
              const data = await response.json();
      
              setHasUsername(data.hasUsername);
              
              // Store the user data from backend
              if (data.user) {
                setUsername(data.user.username);
                setUserName(data.user.name); // Store the name
                setUserId(data.user.id);
                setUserRole(data.user.role);
              }
              setIsLoading(false); // Clear loading on success
            } else {
              console.error("Initial verification failed - signing out existing session:", await response.text());
              
              // Mark as stuck session and clear everything
              if (typeof window !== 'undefined') {
                localStorage.setItem('stuck_session_detected', 'true');
              }
              
              // Force complete sign out for existing sessions that fail verification
              setSession(null);
              setUser(null);
              setUserId(null);
              setHasUsername(null);
              setUsername(null);
              setUserName(null); // Clear name
              setUserRole(null);
              setAvatarUrl(null);
              
              // Sign out from Supabase completely
              await supabase.auth.signOut();
              
              // Clear any potential cached auth data
              if (typeof window !== 'undefined') {
                localStorage.removeItem('supabase.auth.token');
                localStorage.removeItem('sb-auth-token');
              }
            }
          } catch (error) {
            console.error("Error checking username status - signing out existing session:", error);
            
            // Mark as stuck session
            if (typeof window !== 'undefined') {
              localStorage.setItem('stuck_session_detected', 'true');
            }
            
            // Force complete sign out for existing sessions that fail verification
            setSession(null);
            setUser(null);
            setUserId(null);
            setHasUsername(null);
            setUsername(null);
            setUserRole(null);
            setAvatarUrl(null);
            
            // Sign out from Supabase completely
            await supabase.auth.signOut();
            
            // Clear any potential cached auth data
            if (typeof window !== 'undefined') {
              localStorage.removeItem('supabase.auth.token');
              localStorage.removeItem('sb-auth-token');
              // Also clear any other potential Supabase keys
              Object.keys(localStorage).forEach(key => {
                if (key.startsWith('sb-') || key.startsWith('supabase')) {
                  localStorage.removeItem(key);
                }
              });
            }
          }
        }
      } catch (error) {
        console.error("Error getting session:", error);
        setSession(null);
        setUser(null);
        setHasUsername(null);
      } finally {
        setIsLoading(false); // Always clear loading state
      }
    };

    getSession();

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (event: string, session: Session | null) => {
     
      setSession(session);
      setUser(session?.user ?? null);
      setUserId(session?.user?.id ?? null);
      setAvatarUrl(session?.user?.user_metadata?.avatar_url ?? null);

      // Handle different auth events appropriately
      if (event === "SIGNED_IN" && session) {
        // Only handle actual sign-ins, not token refreshes
        setIsLoading(true); // Set loading when starting verification
        try {
          const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
          const response = await fetch(`${apiUrl}/api/user/verify`, {
            method: "POST",
            headers: {
              Authorization: `Bearer ${session.access_token}`,
            },
          }).catch((fetchError) => {
            console.error("Network error during SIGNED_IN verification:", fetchError);
            // Return a mock response object to handle network errors gracefully
            return { ok: false, status: 0, text: async () => 'Network error' } as Response;
          });

          if (response.ok) {
            const data = await response.json();
         
            setHasUsername(data.hasUsername);
            
            // Store the user data from backend
            if (data.user) {
              setUsername(data.user.username);
              setUserId(data.user.id);
              setUserRole(data.user.role);
            }
            
            setIsLoading(false); // Clear loading on success
            
            // Only redirect to dashboard if we're on the home page or login page
            // Don't redirect if user is already navigating within the app
            // const currentPath = window.location.pathname;
           
            // if (currentPath === '/' || currentPath === '/login' || currentPath === '/auth-error') {
         
            //   router.push("/dashboard");
            // }
            // For any other path (like /r0/code), let the user stay where they are
          } else {
            console.error("Backend verification failed:", await response.text());
            setIsLoading(false); // Clear loading on backend error
            
            // Force complete sign out when backend verification fails
            setSession(null);
            setUser(null);
            setUserId(null);
            setHasUsername(null);
            setUsername(null);
            setUserRole(null);
            setAvatarUrl(null);
            
            // Sign out from Supabase completely - DO NOT navigate to dashboard
            await supabase.auth.signOut();
            
         
            if (typeof window !== 'undefined') {
              localStorage.removeItem('supabase.auth.token');
              localStorage.removeItem('sb-auth-token');
              // Also clear any other potential Supabase keys
              Object.keys(localStorage).forEach(key => {
                if (key.startsWith('sb-') || key.startsWith('supabase')) {
                  localStorage.removeItem(key);
                }
              });
              
              window.location.href = '/';
            } else {
              router.push("/"); 
            }
            // Early return to prevent any further execution
            return;
          }
        } catch (error) {
          console.error("Error verifying with backend:", error);
          setIsLoading(false); // Clear loading on network error
          
          // Force complete sign out when verification fails due to network error
          setSession(null);
          setUser(null);
          setUserId(null);
          setHasUsername(null);
          setUsername(null);
          setUserRole(null);
          setAvatarUrl(null);
          
          // Sign out from Supabase completely - DO NOT navigate to dashboard
          await supabase.auth.signOut();
          
          // Clear any potential cached auth data
          if (typeof window !== 'undefined') {
            localStorage.removeItem('supabase.auth.token');
            localStorage.removeItem('sb-auth-token');
            // Also clear any other potential Supabase keys
            Object.keys(localStorage).forEach(key => {
              if (key.startsWith('sb-') || key.startsWith('supabase')) {
                localStorage.removeItem(key);
              }
            });
            // Force reload to ensure clean state - GO TO HOME, NOT DASHBOARD
            window.location.href = '/';
          } else {
            router.push("/"); // GO TO HOME, NOT DASHBOARD
          }
          // Early return to prevent any further execution
          return;
        }
      } else if (event === "SIGNED_OUT") {
        setHasUsername(null);
        setUsername(null);
        setUserId(null);
        setUserRole(null);
        setIsLoading(false); // Clear loading on sign out
      } else if (event === "TOKEN_REFRESHED" && session) {
        // Handle token refresh without redirecting
      
        // Just update the session state, don't verify again or redirect
        setIsLoading(false);
      } else if (event === "INITIAL_SESSION" && session) {
        // Handle initial session load without redirecting if already on a page
    
        // Only clear loading, don't trigger verification again
        setIsLoading(false);
      } else {
        // For any other auth events, clear loading state
        setIsLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, [supabase.auth, router]);
  const signInWithGoogle = async () => {
    try {
   
      
      const { error } = await supabase.auth.signInWithOAuth({
        provider: "google",
        options: {
          redirectTo: `${location.origin}/api/auth/callback`,
          queryParams: {
            prompt: 'select_account', 
          },
        },
      });



      if (error) {
        console.error("Γ¥î Sign-in error:", error);
        throw error;
      }
      
     
    } catch (error) {
      console.error("Γ¥î Error during Google sign-in:", error);
    }
  };

  const signOut = async () => {
    try {
     
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      

      if (currentSession?.provider_token) {
        try {
    
          await fetch(`https://oauth2.googleapis.com/revoke?token=${currentSession.provider_token}`, {
            method: 'POST',
          });
        } catch (revokeError) {
          console.warn('Failed to revoke Google token:', revokeError);
         
        }
      }
      
   
      setSession(null);
      setUser(null);
      setUserId(null);
      setHasUsername(null);
      setUsername(null);
      setUserName(null);
      setUserRole(null);
      setAvatarUrl(null);
      

      await supabase.auth.signOut();
      
    
      if (typeof window !== 'undefined') {
        Object.keys(localStorage).forEach(key => {
          if (key.startsWith('sb-') || key.startsWith('supabase') || key.includes('auth')) {
            localStorage.removeItem(key);
          }
        });
        
        localStorage.removeItem('battlecode_leaderboard');
        localStorage.removeItem('battlecode_rounds');
        localStorage.removeItem('battlecode_locks');
        

        window.location.href = '/';
      } else {
        router.push('/');
      }
    } catch (error) {
      console.error('Error signing out:', error);
      
      setSession(null);
      setUser(null);
      setUserId(null);
      setHasUsername(null);
      setUsername(null);
      setUserRole(null);
      setAvatarUrl(null);
      
      if (typeof window !== 'undefined') {
        // Clear everything possible
        Object.keys(localStorage).forEach(key => {
          if (key.startsWith('sb-') || key.startsWith('supabase') || key.includes('auth') || key.startsWith('battlecode')) {
            localStorage.removeItem(key);
          }
        });
        window.location.href = '/';
      } else {
        router.push('/');
      }
    }
  };
  

  const updateUsername = async (username: string): Promise<boolean> => {
    try {
      if (!session?.access_token) {
        throw new Error("No active session");
      }

      const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
      const response = await fetch(`${apiUrl}/api/user/set-username`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify({ username }),
      });

      if (response.ok) {
        setHasUsername(true);
        return true;
      } else {
        const errorData = await response.json();
        console.error("Username update failed:", errorData.error);
        return false;
      }
    } catch (error) {
      console.error("Error updating username:", error);
      return false;
    }
  };

  return (
    <AuthContext.Provider
      value={{ user, session, isLoading, avatarUrl, hasUsername, username, userName, userId, userRole, signInWithGoogle, signOut, updateUsername }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);

"use client";
import { createContext, useContext, useState, ReactNode } from "react";

// Define the shape of the data we will store
interface Problem {
  id: string;
  title?: string;
  description?: string;
  difficulty?: string;
  constraints?: string[];
  hints?: string[];
  [key: string]: unknown; 
}

interface RoundData {
  problems: Problem[];
  duration: number;
  startTime: number;
}

interface IRoundContext {
  roundData: RoundData | null;
  setRoundData: (data: RoundData | null) => void;
}

const RoundContext = createContext<IRoundContext | null>(null);

export const RoundProvider = ({ children }: { children: ReactNode }) => {
  const [roundData, setRoundData] = useState<RoundData | null>(null);

  return (
    <RoundContext.Provider value={{ roundData, setRoundData }}>
      {children}
    </RoundContext.Provider>
  );
};

export const useRound = () => {
  const context = useContext(RoundContext);
  if (!context) {
    throw new Error("useRound must be used within a RoundProvider");
  }
  return context;
};

